+  it("defaults producer to Spark contributor and grader to Ember", () => {
     assert.equal(DEFAULT_PRODUCER_MODEL, "muse-spark-1.3-contributor");
-    assert.equal(DEFAULT_GRADER_MODEL, "muse-spark-1.3-contributor");
